package com.jobpilot.integration;import com.jobpilot.config.CurrentUserService;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;
@RestController @RequestMapping("/integration")public class IntegrationController{private final SearchPreferenceRepository repo;private final CurrentUserService current;private final JobImportService importer;public IntegrationController(SearchPreferenceRepository r,CurrentUserService c,JobImportService i){repo=r;current=c;importer=i;}public record PreferenceDto(@NotBlank String keywords,@NotBlank String country,String location,boolean remoteOnly,LocalDateTime lastSyncAt){}@GetMapping("/preference")PreferenceDto get(){var p=find();return dto(p);}@PutMapping("/preference")PreferenceDto save(@Valid @RequestBody PreferenceDto d){var p=find();p.setKeywords(d.keywords());p.setCountry(d.country().toLowerCase());p.setLocation(d.location());p.setRemoteOnly(d.remoteOnly());return dto(repo.save(p));}@PostMapping("/sync")SyncResult sync(){return new SyncResult(importer.sync(find()));}private SearchPreference find(){return repo.findByUserId(current.get().getId()).orElseGet(()->{var p=new SearchPreference();p.setUser(current.get());return repo.save(p);});}private PreferenceDto dto(SearchPreference p){return new PreferenceDto(p.getKeywords(),p.getCountry(),p.getLocation(),p.isRemoteOnly(),p.getLastSyncAt());}public record SyncResult(int imported){}}
